let windowSum = 0;

// build the first window
for (let i = 0; i < k; i++) {
  windowSum += arr[i];
}
let best = windowSum;

// slide it
for (let right = k; right < arr.length; right++) {
  windowSum += arr[right];        // the new element enters
  windowSum -= arr[right - k];    // the old element leaves
  best = Math.max(best, windowSum);
}
